protocolTypes.tsDefinition:
| {
      type: 'goal_snapshot';
      goal_version: number;
      session_id: string;
      goal_id: string;
      cursor: GoalCursor;
      state_digest: string;
      goal: GoalRecord;
    }

| {
      type: 'goal_transition';
      goal_version: number;
      session_id: string;
      goal_id: string;
      cursor: GoalCursor;
      transition: string;
      lifecycle: GoalLifecycle;
    }

| {
      type: 'goal_control_refused';
      goal_version: number;
      request_id: string;
      session_id: string;
      goal_id: string;
      reason: string;
    }

export type GoalCursor = {
  /** Schema marks NEITHER field required (no `required` list, additionalProperties:true).
   *  Every shipped fixture populates both. Optional here is the faithful mapping. */
  journal_digest?: string;
  journal_sequence?: number;
};

export type GoalLifecycle = {
  /** Free string in the schema. Only 'running' appears in any fixture. */
  state?: string;
};

export type GoalRecord = {
  /** No field inside `goal` is schema-required; all optional is the faithful mapping. */
  goal_id?: string;
  objective?: string;
  lifecycle?: GoalLifecycle;
  cursor?: GoalCursor;
  authority?: GoalAuthority;
  loop_owner?: GoalLoopOwner;
  loop_owner_epochs?: number;
  iteration_ceiling?: number;
  iterations_started?: number;
  opened_at_unix_ms?: number;
  resume_count?: number;
  tasks?: GoalTaskEntry[];
};

export type GoalAuthority = {
  strategy?: string;
  snapshot_digest?: string;
  parent_envelope_digest?: string;
  effective_limits?: { max_tokens?: number };
  loop_policy?: { kind?: string; iterations?: number };
};

export type GoalLoopOwner = {
  epoch?: number;
  lease_expires_unix_ms?: number;
  strategy?: string;
};

export type GoalTaskEntry = {
  /** The schema's `tasks.items` is an anyOf of TWO shapes: one carrying `outcome`
   *  and no `depends_on` (a completed task), one carrying `depends_on` and no
   *  `outcome` (a blocked task). Both are additionalProperties:true with no
   *  required list, so the merged all-optional shape is exactly what the schema
   *  permits - do NOT model this as a discriminated union; there is no discriminant. */
  task_id?: string;
  status?: string;
  attempts?: number;
  epoch?: number;
  dependency_releases?: number;
  idempotency_key?: string;
  last_transition_seq?: number;
  depends_on?: string[];
  outcome?: { state?: string };
};

| {
      type: 'goal_open';
      goal_version: number;
      request_id: string;
      session_id: string;
      goal_id: string;
      objective: string;
      iterations: number;
      strategy: string;
      max_tokens: number;
    }

| {
      type: 'goal_declare_task';
      goal_version: number;
      request_id: string;
      session_id: string;
      goal_id: string;
      task_id: string;
      /** NOT in the schema's required list, though the fixture sends both. */
      depends_on?: string[];
      idempotency_key?: string;
    }

| {
      type: 'goal_advance';
      goal_version: number;
      request_id: string;
      session_id: string;
      goal_id: string;
      cursor: GoalCursor;
    }

| {
      type: 'goal_cancel';
      goal_version: number;
      request_id: string;
      session_id: string;
      goal_id: string;
      cursor: GoalCursor;
    }

| {
      type: 'goal_resync';
      goal_version: number;
      request_id: string;
      session_id: string;
      /** goal_id is NOT in this command's required list (unlike every other goal
       *  command), although the example payload sends it. Omitting it plausibly
       *  means "resync every goal in the session" - the contract does not say. */
      goal_id?: string;
    }
